function countOpenBrackets(brackets: string, n: int): int
    requires 0 <= n <= brackets.Length
    ensures 0 <= countOpenBrackets(brackets, n) <= n
{
    var count := 0;
    var i := 0;
    while i < n
        invariant 0 <= i <= n
        invariant count == countOpenBrackets(brackets, i)
    {
        if brackets[i] == '<' {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

function countCloseBrackets(brackets: string, n: int): int
    requires 0 <= n <= brackets.Length
    ensures 0 <= countCloseBrackets(brackets, n) <= n
{
    var count := 0;
    var i := 0;
    while i < n
        invariant 0 <= i <= n
        invariant count == countCloseBrackets(brackets, i)
    {
        if brackets[i] == '>' {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}
